--
-- Name: daily_sales; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.daily_sales AS
 SELECT sale_date,
    count(*) AS sales_count,
    (COALESCE(sum(total), (0)::numeric))::numeric(14,2) AS total
   FROM public.sales
  WHERE ((status)::text = 'completed'::text)
  GROUP BY sale_date;


